-- Donnees de demonstration pour H2 / Hibernate.
-- Prerequis : tables creees par JPA, base de test vide.
-- Les dates de publication completes sont indicatives lorsque seule l'annee est retenue.
-- Les comptes sont fictifs et leurs mots de passe ne permettent pas une authentification reelle.







-- MYSQL
ALTER TABLE auteur AUTO_INCREMENT = 32;
ALTER TABLE editeur AUTO_INCREMENT = 31;
ALTER TABLE collection AUTO_INCREMENT = 6;
ALTER TABLE livre AUTO_INCREMENT = 36;
ALTER TABLE avis AUTO_INCREMENT = 266;
ALTER TABLE compte AUTO_INCREMENT = 4;

-- H2
-- ALTER TABLE auteur ALTER COLUMN id RESTART WITH 32;
-- ALTER TABLE editeur ALTER COLUMN id RESTART WITH 31;
-- ALTER TABLE collection ALTER COLUMN id RESTART WITH 6;
-- ALTER TABLE livre ALTER COLUMN id RESTART WITH 36;
-- ALTER TABLE avis ALTER COLUMN id RESTART WITH 266;
-- ALTER TABLE compte ALTER COLUMN id RESTART WITH 4;