INSERT INTO livre (id, titre, resume, date, auteur, editeur, collection) VALUES
(1, 'Voyage au centre de la Terre', 'Le professeur Otto Lidenbrock découvre un manuscrit indiquant un passage vers le centre de la Terre. Accompagné de son neveu Axel et du guide Hans, il entreprend une expédition extraordinaire dans les profondeurs du globe.', '1864-01-01', 1, 1, 1),
(2, 'Illuminations', 'Recueil de poèmes en prose et en vers libres explorant des visions oniriques, des paysages imaginaires et des expériences sensorielles. Rimbaud y renouvelle profondément le langage poétique.', '1886-01-01', 2, 2, 2),
(3, 'Vingt mille lieues sous les mers', 'Le professeur Pierre Aronnax, son domestique Conseil et le harponneur Ned Land sont capturés par le mystérieux capitaine Nemo. À bord du Nautilus, ils découvrent les merveilles et les dangers des profondeurs océaniques.', '1870-01-01', 1, 1, 1),
(4, 'Le Tour du monde en quatre-vingts jours', 'Phileas Fogg, un gentleman britannique, parie qu''il peut faire le tour du monde en quatre-vingts jours. Accompagné de son domestique Passepartout, il traverse plusieurs continents et affronte de nombreux obstacles pour tenir son pari.', '1872-01-01', 1, 1, 1),
(5, 'Une saison en enfer', 'Recueil de poèmes en prose dans lequel Arthur Rimbaud explore ses expériences personnelles, ses désillusions et sa quête de liberté. À travers une écriture intense et novatrice, il remet en question les conventions morales, religieuses et littéraires.', '1873-01-01', 2, 3, 2),
(6, 'L''Île mystérieuse', 'Cinq hommes échouent sur une île isolée et utilisent leurs connaissances scientifiques pour survivre, tandis que des événements inexpliqués éveillent leur curiosité.', '1874-01-01', 1, 1, 1),
(7, 'Les Trois Mousquetaires', 'D''Artagnan rejoint Athos, Porthos et Aramis dans une aventure de cape et d''épée mêlant amitié, intrigues et rivalités politiques.', '1844-01-01', 3, 4, 3),
(8, 'Les Misérables', 'Le destin de Jean Valjean croise celui de personnages confrontés à la pauvreté, à l''injustice et aux bouleversements de la société française.','1862-01-01', 4, 5, 4),
(9, 'Voyage au bout de la nuit', 'Ferdinand Bardamu traverse la guerre, les colonies et la société industrielle dans un roman marqué par une critique sombre de la condition humaine.', '1932-01-01', 5, 6, 2),
(10, 'Les Particules élémentaires', 'Deux demi-frères aux parcours opposés incarnent les transformations des relations humaines, de la sexualité et de la société contemporaine.', '1998-01-01', 6, 7, 2),
(11, 'Atlas Shrugged', 'Dans une société en crise, plusieurs industriels et inventeurs se retirent progressivement du monde, sur fond de débat philosophique autour de l’individualisme et de l’économie.', '1957-01-01', 7, 8, 2),
(12, 'Harry Potter and the Philosopher''s Stone', 'Un jeune orphelin découvre qu''il est sorcier et entre à l''école de Poudlard, où il se lie d''amitié avec d''autres élèves et enquête sur un mystère.', '1997-01-01', 8, 9, 5),
(13, 'The Satanic Verses', 'Après un accident aérien, deux personnages connaissent des transformations extraordinaires dans un récit mêlant migration, identité, rêve et religion.', '1988-01-01', 9, 10, 2),
(14, 'American Psycho', 'À New York, un jeune financier mène une vie mondaine dont le récit révèle progressivement une violence extrême et une satire de la consommation.', '1991-01-01', 10, 11, 2),
(15, 'Le Temps des combats', 'Récit de son parcours politique et de son expérience du pouvoir.', '2023-01-01', 11, 12, 2),
(16, 'Les Leçons du pouvoir', 'Réflexions sur son mandat présidentiel et les décisions de gouvernement.', '2018-01-01', 12, 13, 2),
(17, 'À contre flots', 'Essai autobiographique et politique exposant ses positions.', '2006-01-01', 13, 14, 2),
(18, 'Faites mieux ! Vers la Révolution citoyenne', 'Essai présentant des propositions politiques et institutionnelles.', '2023-01-01', 14, 15, 2),
(19, 'La France n’a pas dit son dernier mot', 'Essai politique sur l’identité et la société françaises.', '2021-01-01', 15, 16, 2),
(20, 'Des hommes qui lisent', 'Réflexions personnelles sur les lectures et la littérature.', '2017-01-01', 16, 17, 2),
(21, 'Fugue américaine', 'Roman inspiré de la vie de deux pianistes et de leur entourage.', '2023-01-01', 17, 18, 2),
(22, 'Faire', 'Essai présentant une vision et des propositions de réforme.', '2015-01-01', 18, 19, 2),
(23, 'Ce que je peux enfin vous dire', 'Témoignage sur son parcours et son expérience politique.', '2018-01-01', 19, 12, 2),
(24, 'Ce que je cherche', 'Récit autobiographique et exposé de positions politiques.', '2024-01-01', 20, 12, 2),
(25, 'Great Again: How to Fix Our Crippled America', 'Essai présentant les thèmes de sa campagne et ses propositions politiques.', '2015-01-01', 21, 20, 2),
(26, 'A Promised Land', 'Mémoires consacrés à son parcours et aux premières années de sa présidence.', '2020-01-01', 22, 21, 2),
(27, 'What Happened', 'Retour personnel sur la campagne présidentielle américaine de 2016.', '2017-01-01', 23, 22, 2),
(28, 'Unleashed', 'Mémoires politiques portant notamment sur le Brexit et son mandat.', '2024-01-01', 24, 23, 2),
(29, 'First Person: An Astonishingly Frank Self-Portrait by Russia’s President', 'Entretiens autobiographiques sur son parcours et sa vision politique.', '2000-01-01', 25, 24, 2),
(30, 'Io sono Giorgia', 'Autobiographie et présentation de convictions politiques.', '2021-01-01', 26, 25, 2),
(31, 'El camino del libertario', 'Essai exposant sa conception libertarienne de l’économie et de la politique.', '2022-01-01', 27, 26, 2),
(32, 'The Truths We Hold', 'Mémoires sur son parcours dans la justice et la politique.', '2019-01-01', 28, 27, 2),
(33, 'Freiheit', 'Mémoires consacrés à sa vie et à ses années à la chancellerie.', '2024-01-01', 29, 28, 2),
(34, 'Révolution', 'Essai présentant une vision politique et un projet de transformation.', '2016-01-01', 30, 29, 2),
(35, 'Mein Kampf', 'Texte de propagande national-socialiste et antisémite exposant une idéologie raciste et expansionniste ; document historique à étudier avec un appareil critique.', '1925-01-01', 31, 30, 2);
INSERT INTO avis (id, note, commentaire, date, livre_id) VALUES
(1, 5, 'Un roman d''aventure captivant qui mêle exploration, science et imagination. Jules Verne parvient à nous transporter dans un univers fascinant, avec des personnages attachants et de nombreux rebondissements.', '2026-11-02', 1),
(2, 4, 'Une œuvre poétique intense et originale, portée par des images saisissantes et une grande liberté d''écriture. Certains passages demandent plusieurs lectures, mais la richesse des textes rend l''expérience particulièrement intéressante.', '2026-11-04', 2),
(3, 5, 'Une aventure extraordinaire où Jules Verne mêle suspense, découvertes scientifiques et exploration sous-marine. Le capitaine Nemo est un personnage mystérieux et fascinant.', '2026-10-15', 3),
(4, 4, 'Un récit passionnant qui nous entraîne dans un voyage autour du monde riche en péripéties. L''ingéniosité des personnages et les descriptions des différents pays rendent la lecture particulièrement agréable.', '2026-10-22', 4),
(5, 5, 'Un recueil de poèmes remarquable par sa liberté d''expression et la puissance de ses images. Arthur Rimbaud y aborde des thèmes variés avec une sensibilité et une originalité qui marquent durablement le lecteur.', '2026-11-01', 5),
(6, 4, 'Un voyage fascinant dans les profondeurs de la Terre, où Jules Verne parvient à mêler découvertes scientifiques et aventures extraordinaires. Les descriptions des paysages souterrains sont particulièrement immersives.', '2026-10-28', 1),
(7, 5, 'Une œuvre poétique saisissante dans laquelle Arthur Rimbaud explore les limites du langage et de l''imagination. Chaque poème offre une expérience singulière, entre visions fantastiques et réflexions profondes.', '2026-11-03', 2),
(8, 5, 'Un roman ingénieux où l''entraide et la science jouent un rôle central. Les mystères de l''île maintiennent l''intérêt jusqu''à la fin.', '2026-10-30', 6),
(9, 4, 'Des personnages mémorables et une intrigue pleine de rebondissements. Une lecture rythmée et divertissante.', '2026-11-05', 7),
(10, 5, 'Un récit émouvant sur la justice et la rédemption, porté par des personnages complexes et attachants.', '2026-11-06', 8),
(11, 4, 'Une écriture marquante et une vision très sombre de la société. Le style oral donne une force singulière au récit.', '2026-11-06', 9),
(12, 3, 'Un roman provocateur qui aborde la solitude et les transformations sociales. Certaines thèses peuvent susciter le désaccord.', '2026-11-06', 10),
(13, 3, 'Un récit ambitieux où l’intrigue sert aussi à exposer des idées philosophiques et économiques discutables.', '2026-11-06', 11),
(14, 5, 'Un début de saga accessible et inventif, avec un univers magique très détaillé et des personnages attachants.', '2026-11-06', 12),
(15, 4, 'Une construction narrative exigeante et inventive, qui aborde des questions complexes d''identité et de croyance.', '2026-11-06', 13),
(16, 3, 'Une satire dérangeante de la société de consommation, dont la violence explicite peut rebuter.', '2026-11-06', 14),
(17, 4, 'Avis fictif de démonstration : ouvrage utile pour examiner son contexte, ses arguments et sa réception critique.', '2026-11-06', 15),
(18, 6, 'Avis fictif de démonstration : ouvrage utile pour examiner son contexte, ses arguments et sa réception critique.', '2026-11-06', 16),
